const app = document.querySelector('#app');
const toast = document.querySelector('#toast');
const session = JSON.parse(localStorage.getItem('jigoku-session') || 'null');
let state = null, stream = null, tick = null, previewParticipantId = null, gmTab = 'progress', dismissedResultKey = null, freeTimeView = 'rest', narrativeScrollPending = false;

const esc = value => String(value ?? '').replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
const statusDisplayNames = Object.freeze({ COOLDOWN_EXTENSION: '【強奪】', ATTACK_DAMAGE_DOWN: '攻撃ダメージ低下', POISON: '毒', BURN: '火傷', TARGET_RESTRICTION: '対象制限' });
const statusDisplayName = value => statusDisplayNames[value] || value;
const playerFacingText = value => Object.entries(statusDisplayNames).reduce((text, [key, label]) => text.replaceAll(key, label), String(value ?? ''));
const narrativeText = value => esc(playerFacingText(value)).replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>');
const categoryName = value => ({ attack: '攻撃', defense: '防御', support: '補助', heal: '回復', interference: '妨害' }[value] || value);
const CURRENCY_TYPES = [['one', '壱', 1], ['two', '弐', 2], ['three', '参', 3], ['five', '伍', 5], ['seven', '漆', 7]];
const currencyCoinsLabel = coins => CURRENCY_TYPES.filter(([type]) => coins?.[type]).map(([type, label]) => `${label}×${coins[type]}`).join('、') || 'なし';
const phaseName = () => ({ LOBBY: '乗車受付', INTRODUCTION: '導入', SELF_INTRODUCTION: '自己紹介', GAME_GUIDE: 'ゲーム説明', PACK_SELECTION: 'パック選択', TURN_SELECTION: 'カード秘密選択', TURN_RESULT: 'ターン結果', STATION_RESULT: '駅結果', REWARD_NARRATION: '報酬発表', CURRENCY_SYNC_WAIT: '冥貨反映待機', FREE_TIME_INTRO: '自由時間の案内', FREE_TIME: '自由時間・休憩', STATION_INTRODUCTION: '駅導入', FINAL_RANKING: '最終順位', FINAL_ALIGNMENT: '最終整線', FINAL_JUDGMENT: 'GM最終判定', ENDING: 'エンディング' }[state.phase]);
const narrativeStep = value => value?.phase === 'INTRODUCTION' ? value.introductionStep : value?.phase === 'GAME_GUIDE' ? value.gameGuide?.step : value?.phase === 'STATION_INTRODUCTION' ? value.stationIntroduction?.step : value?.phase === 'REWARD_NARRATION' ? value.rewardNarration?.step : value?.phase === 'FREE_TIME_INTRO' ? value.freeTimeIntroduction?.step : null;
const narrativeProgressed = (before, after) => Boolean(before && before.phase === after?.phase && narrativeStep(before) !== null && narrativeStep(after) > narrativeStep(before));
const INTRODUCTION_LINES = [
  'ガタン、ガタン。',
  '規則正しい揺れと、車輪が線路を擦る音。',
  '目を開けると、そこは見知らぬ列車の中だった。窓の外には、景色らしい景色はない。',
  'そして車内には、自分を含め、七人の人間がいた。',
  '誰も、この列車に乗った覚えはない。',
  'どうしてここにいるのか。どこへ向かっているのか。',
  '何ひとつ分からないまま、列車だけが進み続けている。',
  'そのとき、勢いよく車両の扉が開いた。',
  '「はぁ〜い！」',
  '「みなさ〜ん！ お目覚めですかぁ？」',
  '現れたのは、小さな角を生やした奇妙な生き物だった。',
  '車掌帽をかぶり、ぶかぶかの制服を着ている。その手には、人数分の切符が握られていた。',
  '「いやぁ〜、よかったよかった！」',
  '「七名様、ちゃ〜んと揃ってますねぇ！」',
  '「それでは改めまして」',
  '小鬼は帽子を押さえ、深々と頭を下げる。',
  '「ようこそ！地獄廻線へ！」',
  '聞き慣れない言葉が、車内に響く。',
  '「この列車はこれから、七つの地獄を順番に巡りま〜す！」',
  '「焦熱、氷結、針山、血の池、餓鬼、修羅……」',
  '「そして最後は、無間地獄！」',
  '「いやぁ、観光列車みたいで楽しそうですねぇ！」',
  '小鬼は楽しそうに笑う。',
  '「あっ、大事なことを忘れてました！」',
  '「みなさん……」',
  '少しだけ間を置いて。',
  '「もう死んでますからねぇ。」',
  '「なのでぇ、ここから先は生きてた頃の常識なんて、あんまり役に立ちませ〜ん！」',
  '「七つの地獄を巡って、最後までちゃ〜んと乗っていてくださいね！」',
  'その直後。車内放送のチャイムが鳴る。',
  '――ピンポーン。',
  '『まもなく――第一地獄。』',
  '『焦熱地獄。』',
  '「さぁ！」',
  '「その前に、せっかく七人もいるんですから」',
  '「まずは、お互いのことを知っておきましょうか！」',
  'こうして。',
  '行き先も、降り方も分からないまま。',
  '七人を乗せた地獄廻線は、最初の駅へと走り始めた。'
];
const mePublic = id => state.players.find(player => player.participantId === id);
const cardName = id => state.packs.flatMap(pack => pack.cards || []).find(card => card.id === id)?.name || id || 'なし';
const playerName = id => { const player = mePublic(id); return player ? `PL${player.playerNumber} ${player.name}` : '対象なし'; };
const currencySummary = currency => [['one', '壱'], ['two', '弐'], ['three', '参'], ['five', '伍'], ['seven', '漆']].filter(([key]) => Number(currency?.[key]) > 0).map(([key, label]) => `${label} ${currency[key]}`).join('｜') || 'なし';

function notify(message) { toast.textContent = message; toast.style.display = 'block'; setTimeout(() => toast.style.display = 'none', 3500); }
async function request(path, options = {}) { const response = await fetch(path, { ...options, headers: { 'content-type': 'application/json', ...(session?.token ? { authorization: `Bearer ${session.token}` } : {}) } }); const data = await response.json(); if (!response.ok) throw new Error(data.error); return data; }
function saveSession(data) { localStorage.setItem('jigoku-session', JSON.stringify(data)); location.reload(); }
async function action(type, payload = {}) { try { const previous = state; const nextState = await request(`/api/rooms/${session.roomCode}/actions`, { method: 'POST', body: JSON.stringify({ type, ...payload }) }); narrativeScrollPending ||= narrativeProgressed(previous, nextState); state = nextState; render(); } catch (error) { notify(error.message); } }

document.querySelector('#createForm')?.addEventListener('submit', async event => { event.preventDefault(); try { const form = new FormData(event.target); saveSession(await request('/api/rooms', { method: 'POST', body: JSON.stringify({ name: form.get('name'), playtestMode: form.get('playtestMode') === 'on' }) })); } catch (error) { notify(error.message); } });
document.querySelector('#testRoom')?.addEventListener('click', async () => { try { saveSession(await request('/api/test-room', { method: 'POST', body: '{}' })); } catch (error) { notify(error.message); } });
document.querySelector('#joinForm')?.addEventListener('submit', async event => { event.preventDefault(); const form = new FormData(event.target); try { saveSession(await request(`/api/rooms/${form.get('code').toUpperCase()}/join`, { method: 'POST', body: JSON.stringify({ name: form.get('name') }) })); } catch (error) { notify(error.message); } });

async function connect() { if (!session) return; try { state = await request(`/api/rooms/${session.roomCode}/state`); render(); const issued = await request(`/api/rooms/${session.roomCode}/stream-ticket`, { method: 'POST', body: '{}' }); stream = new EventSource(`/api/rooms/${session.roomCode}/events?ticket=${encodeURIComponent(issued.ticket)}`); stream.addEventListener('state', event => { const previous = state; const nextState = JSON.parse(event.data); narrativeScrollPending ||= narrativeProgressed(previous, nextState); state = nextState; render(); }); stream.onerror = () => {}; } catch (error) { localStorage.removeItem('jigoku-session'); notify(error.message); setTimeout(() => location.reload(), 1200); } }

function timerHtml(compact = false) { if (!state.timer) return '<span class="timer-empty">--:--</span>'; const remaining = Math.max(0, Math.ceil((state.timer.endsAt - Date.now()) / 1000)); return `<span class="timer ${compact ? 'compact' : ''} ${remaining <= 30 ? 'warning' : ''}">${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2, '0')}</span>`; }
function gameHeaderHtml(roleLabel) { const station = state.station; const turn = state.phase === 'STATION_INTRODUCTION' ? `— / ${station?.turnCount || '—'}` : station ? `${state.stationTurn} / ${station.turnCount}` : '—'; return `<section class="game-header"><div><span class="eyebrow">${esc(roleLabel)}</span><strong>${station ? esc(station.name) : phaseName()}</strong></div><div class="header-stat"><span>TURN</span><b>${turn}</b></div><div class="header-stat"><span>PHASE</span><b>${phaseName()}</b></div><div class="header-stat timer-stat"><span>TIME</span>${timerHtml(true)}</div>${station ? `<div class="station-effect"><span>駅効果</span><b>${esc(station.effect)}</b></div>` : ''}</section>`; }

function introductionHtml() { return `<section class="panel script"><span class="eyebrow">導入「地獄廻線」</span><h2>地獄廻線</h2>${INTRODUCTION_LINES.map((line, index) => `<p ${index >= state.introductionStep ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function applyIntroductionProgress() { if (state.phase !== 'INTRODUCTION') return; document.querySelectorAll('.script').forEach(script => { script.querySelectorAll(':scope > p').forEach((element, index) => { element.hidden = index >= state.introductionStep; }); }); }
function introductionAdvanceHtml() { return `<div class="actions intro-actions"><button id="advanceIntro">${state.introductionStep >= INTRODUCTION_LINES.length ? '自己紹介8分へ' : '次へ'}</button></div>`; }
function gameGuideHtml() { const guide = state.gameGuide; if (!guide) return ''; return `<section class="panel script"><span class="eyebrow">${esc(guide.title)}</span><h2>${esc(guide.title)}</h2>${guide.lines.map((line, index) => `<p ${index >= guide.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function gameGuideAdvanceHtml() { const guide = state.gameGuide; if (!guide) return ''; return `<div class="actions intro-actions"><button id="advanceGameGuide">${guide.step >= guide.lines.length ? 'パック選択へ' : '次へ'}</button></div>`; }
function stationIntroductionHtml() { const introduction = state.stationIntroduction; if (!introduction) return ''; return `<section class="panel script station-script"><span class="eyebrow">${esc(introduction.title)}</span><h2>${esc(state.station?.name || '')}</h2>${introduction.lines.map((line, index) => `<p data-station-line ${index >= introduction.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function stationIntroductionAdvanceHtml() { const introduction = state.stationIntroduction; if (!introduction) return ''; return `<div class="actions intro-actions"><button id="advanceStationIntro">${introduction.step >= introduction.lines.length ? `${esc(state.station.name)}を開始` : '次へ'}</button></div>`; }
function rewardNarrationHtml() { const narration = state.rewardNarration; if (!narration) return ''; return `<section class="panel script reward-script"><span class="eyebrow">報酬発表</span><h2>${esc(narration.title)}</h2>${narration.lines.map((line, index) => `<p ${index >= narration.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function rewardNarrationAdvanceHtml() { const narration = state.rewardNarration; if (!narration) return ''; return `<div class="actions intro-actions"><button id="advanceRewardNarration">${narration.step >= narration.lines.length ? state.stationResult?.noCurrencyRewards ? '最終順位へ' : '冥貨反映待機へ' : '次へ'}</button></div>`; }
function freeTimeIntroductionHtml() { const narration = state.freeTimeIntroduction; if (!narration) return ''; return `<section class="panel script reward-script"><span class="eyebrow">自由時間</span><h2>${esc(narration.title)}</h2>${narration.lines.map((line, index) => `<p ${index >= narration.step ? 'hidden' : ''}>${narrativeText(line)}</p>`).join('')}</section>`; }
function freeTimeIntroductionAdvanceHtml() { const narration = state.freeTimeIntroduction; if (!narration) return ''; return `<div class="actions intro-actions"><button id="advanceFreeTimeIntroduction">${narration.step >= narration.lines.length ? '自由時間を開始' : '次へ'}</button></div>`; }
function rewardSummaryHtml(result = state.stationResult) { if (!result?.rewardSummary) return ''; return `<div class="reward-summary">${result.rewardSummary.map(entry => { const player = state.players.find(item => item.participantId === entry.participantId); return `<article><b>PL${entry.playerNumber} ${esc(player?.name || '')}</b><span>順位：${entry.rank ? `${entry.rank}位` : '対象外'}</span><span>順位報酬：壱×${entry.rankReward}</span><span>支援賞：壱×${entry.supportAward}</span><span>特殊ボーナス：壱×${entry.specialBonus}</span><strong>合計：壱×${entry.totalOne}</strong></article>`; }).join('')}</div>`; }
function currencySyncWaitHtml(me) { const reward = state.stationResult?.rewardSummary?.find(entry => entry.participantId === me.participantId); return `<section class="focus-panel currency-sync-wait"><span class="eyebrow">COCOFORIA SYNC</span><h2>冥貨の反映待機</h2><p>GMが今回獲得した冥貨をココフォリアへ反映しています。しばらくお待ちください。</p><div class="earned-currency"><span>今回の獲得</span><strong>壱×${reward?.totalOne || 0}</strong></div><p class="meta">反映が完了するまで、ショップ購入・冥貨譲渡・次駅への進行はできません。</p>${rewardSummaryHtml()}</section>`; }
function finalRankingHtml() { const rankings = state.finalRanking || []; return `<section class="focus-panel station-result"><span class="eyebrow">FINAL RANKING</span><h2>ゲーム全体の最終順位</h2><p>最終HP、総与ダメージ、総支援点、総被ダメージの順に判定しています。</p><div class="reward-summary">${rankings.map(entry => { const player = state.players.find(item => item.participantId === entry.participantId); return `<article><b>${entry.rank}位　PL${entry.playerNumber} ${esc(player?.name || '')}</b><span>最終HP：${entry.hp}</span><span>総与ダメージ：${entry.totalDamageDealt}</span><span>総支援点：${entry.totalSupport}</span><span>総被ダメージ：${entry.totalDamageTaken}</span></article>`; }).join('') || '<p>最終順位を集計しています。</p>'}</div></section>`; }
function finalAlignmentHtml() { return `<section class="focus-panel station-result"><span class="eyebrow">FINAL ALIGNMENT</span><h2>最終整線</h2><div class="intro-timer">${timerHtml()}</div><p>ココフォリア上で、所有する使用可能な冥貨を使って最終整線を行ってください。</p><p class="meta">ショップ購入・譲渡・戦闘カードの使用はできません。終了後はGMが盤面を非公開で判定します。</p></section>`; }
function finalJudgmentHtml() { return `<section class="focus-panel station-result"><span class="eyebrow">GM FINAL JUDGMENT</span><h2>GM最終判定</h2><p>ココフォリア盤面をロックし、天国線と終着ホームの成立を非公開で確認してください。</p><p class="meta">判定後、エンディングを確定します。</p></section>`; }
function endingHtml() { return `<section class="focus-panel station-result"><span class="eyebrow">ENDING</span><h2>${esc(state.finalEnding?.title || 'エンディング')}</h2><p>GMが最終判定を確定しました。</p></section>`; }
const surveyChecked = (values, value) => Array.isArray(values) && values.includes(value) ? 'checked' : '';
const surveyRating = (name, value) => `<div class="survey-rating">${[1, 2, 3, 4, 5].map(rating => `<label><input type="radio" name="${name}" value="${rating}" ${Number(value) === rating ? 'checked' : ''}> ${rating}</label>`).join('')}</div>`;
const surveyChecks = (name, choices, values = []) => `<div class="survey-checks">${choices.map(([value, label]) => `<label><input type="checkbox" name="${name}" value="${value}" ${surveyChecked(values, value)}> ${esc(label)}</label>`).join('')}</div>`;
const surveySelect = (name, choices, value, placeholder = '未回答') => `<select name="${name}"><option value="">${placeholder}</option>${choices.map(([id, label]) => `<option value="${id}" ${value === id ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select>`;
function surveyAnswersFor(me) { return state.me.role === 'GM' ? state.playtest?.surveys?.find(entry => entry.participantId === me.participantId)?.answers || null : state.playtest?.survey || null; }
function playtestSurveyHtml(me) {
  if (!state.playtest?.enabled) return '';
  const answers = surveyAnswersFor(me) || {};
  const ownCards = me.cards || [];
  const ownedShops = me.shopInventory || [];
  const wantedShops = (state.shop?.items || []).filter(item => !ownedShops.some(entry => entry.itemId === item.id));
  const cards = ownCards.map(card => [card.id, card.name]);
  const lateChoices = [['WANTED', '欲しいと思った'], ['NO_CURRENCY', '欲しかったがお金がなかった'], ['WEAK', '効果が弱いと思った'], ['UNCLEAR', '使う場面が分からなかった'], ['OTHER_SHOP', '既存SHOPを優先した'], ['UNNECESSARY', '必要ないと思った']];
  return `<section class="panel playtest-survey"><span class="eyebrow">PLAYTEST SURVEY</span><h2>プレイ後アンケート</h2><p class="meta">任意回答です。回答内容はゲーム結果・順位には影響しません。</p><form id="playtestSurvey"><fieldset><legend>Q1　使ったカードパックは楽しかったですか？</legend>${surveyRating('packFun', answers.packFun)}</fieldset><fieldset><legend>Q2　自分のパックは強いと感じましたか？</legend>${surveyRating('packStrength', answers.packStrength)}</fieldset><fieldset><legend>Q3　使いにくかったカードはありましたか？</legend>${surveyChecks('difficultCardIds', cards, answers.difficultCardIds)}<textarea name="difficultText" placeholder="自由記述（任意）">${esc(answers.difficultText || '')}</textarea></fieldset><fieldset><legend>Q4　強すぎると感じたカードはありましたか？</legend>${surveyChecks('strongCardIds', cards, answers.strongCardIds)}<textarea name="strongText" placeholder="自由記述（任意）">${esc(answers.strongText || '')}</textarea></fieldset><fieldset><legend>Q5　購入したSHOPカードで「買ってよかった」と感じたものは？</legend>${ownedShops.length ? surveyChecks('worthwhileShopIds', ownedShops.map(entry => [entry.itemId, entry.item.name]), answers.worthwhileShopIds) : '<p class="meta">購入したSHOPカードはありません。</p>'}</fieldset><fieldset><legend>Q6　欲しかったが買わなかったSHOPは？</legend>${wantedShops.length ? surveyChecks('wantedShopIds', wantedShops.map(item => [item.id, item.name]), answers.wantedShopIds) : '<p class="meta">該当するSHOPカードはありません。</p>'}</fieldset><fieldset><legend>Q7　SHOPの商品数はどうでしたか？</legend>${surveySelect('shopCount', [['TOO_FEW', '少ない'], ['JUST_RIGHT', 'ちょうどよい'], ['TOO_MANY', '多い']], answers.shopCount)}</fieldset><fieldset><legend>Q8　冥貨のおつりについて、何か意味があると思いましたか？</legend>${surveySelect('primeMeaning', [['YES', 'はい'], ['NO', 'いいえ'], ['NOTICED_DURING', '途中で気づいた']], answers.primeMeaning)}</fieldset><fieldset><legend>Q9　素数冥貨をショップで使うか、残しておくか迷いましたか？</legend>${surveySelect('primeSpendingDilemma', [['YES', 'はい'], ['NO', 'いいえ']], answers.primeSpendingDilemma)}</fieldset>${me.packId === 'blood' ? `<fieldset><legend>血の池パック：他のPLを回復することにメリットを感じましたか？</legend>${surveyRating('bloodHealingBenefit', answers.blood?.healingBenefit)}</fieldset><fieldset><legend>血の池パック：他人を回復すると、相手を有利にしてしまうと感じましたか？</legend>${surveyRating('bloodHealingHelpsOthers', answers.blood?.healingHelpsOthers)}</fieldset><fieldset><legend>血の池パック：輸血のHP−1は重いと感じましたか？</legend>${surveyRating('bloodTransfusionCost', answers.blood?.transfusionCost)}</fieldset><fieldset><legend>血の池パックでは、何を中心にプレイしましたか？</legend>${surveySelect('bloodFocus', [['ATTACK_ABSORB', '攻撃・吸収'], ['HEAL_SUPPORT', '回復・支援'], ['INTERFERENCE', '妨害'], ['DEFENSE_REFLECTION', '防御・反射'], ['BALANCED', 'バランス型']], answers.blood?.focus)}</fieldset>` : ''}<fieldset><legend>第六SHOPについて（複数選択可）</legend>${[['enma-eye', '閻魔の眼'], ['six-realms-chain', '六道の鎖'], ['infinite-slip', '無間の札']].map(([itemId, name]) => `<div class="late-shop-survey"><b>${name}</b>${surveyChecks(`lateShop-${itemId}`, lateChoices, answers.lateShop?.[itemId])}</div>`).join('')}</fieldset><fieldset><legend>Q10　自由記述</legend><textarea name="comments" placeholder="気づいたこと・感想（任意）">${esc(answers.comments || '')}</textarea></fieldset><button class="primary-action" type="submit">${answers.submittedAt ? '回答を更新する' : '回答を送信する'}</button>${answers.submittedAt ? `<p class="success-message">送信済み：${esc(new Date(answers.submittedAt).toLocaleString('ja-JP'))}</p>` : ''}</form></section>`;
}
function selfIntroductionHtml(viewerId = null) { const viewer = viewerId ? mePublic(viewerId) : null; const completion = viewer ? (viewer.selfIntroductionComplete ? '<p class="success-message">自己紹介完了を送信しました。全員の完了をお待ちください。</p>' : `<button class="primary-action" ${state.me.role === 'GM' ? `data-test-self-intro="${viewerId}"` : 'id="selfIntroDone"'}>自己紹介終わった</button>`) : ''; return `<section class="focus-panel"><span class="eyebrow">CURRENT ACTION</span><h2>自己紹介をしてください</h2><div class="intro-timer">${timerHtml()}</div><p>終わったPLから完了ボタンを押してください。</p><div class="compact-players">${state.players.map(player => `<div><b>PL${player.playerNumber} ${esc(player.name)}</b><span class="pill ${player.selfIntroductionComplete ? 'confirmed' : 'pending'}">${player.selfIntroductionComplete ? '完了' : '進行中'}</span></div>`).join('')}</div>${completion}</section>`; }

function scrollNarrativeIntoView() { const target = document.querySelector('.intro-actions') || [...document.querySelectorAll('.script > p')].filter(line => !line.hidden).at(-1); target?.scrollIntoView({ behavior: 'smooth', block: 'end' }); }
function render() { if (!state) return; base(); if (state.me.role === 'GM') renderGm(); else renderPlayer(); bindFreeTimeNavigation(); showResultModal(); showPurchaseModal(); applyIntroductionProgress(); if (narrativeScrollPending) { narrativeScrollPending = false; requestAnimationFrame(scrollNarrativeIntoView); } clearInterval(tick); tick = setInterval(updateTimer, 1000); }
function updateTimer() { document.querySelectorAll('.timer').forEach(old => { old.outerHTML = timerHtml(old.classList.contains('compact')); }); const finish = document.querySelector('#openPacks'); if (finish && state.timer && Date.now() >= state.timer.endsAt) { finish.disabled = false; finish.textContent = '自己紹介を終了してパック選択へ'; } }
function base() { document.querySelector('#roomBadge').innerHTML = `<span class="pill">ROOM ${esc(state.code)}</span> <button class="secondary small" id="leave">退出</button>`; setTimeout(() => document.querySelector('#leave')?.addEventListener('click', () => { localStorage.removeItem('jigoku-session'); location.reload(); }), 0); }

function renderPlayer() { const me = state.me; if (state.phase === 'LOBBY') return renderSimple(`<h2>乗車待機中</h2><p>PL${me.playerNumber} ${esc(me.name)}</p><p>参加者 ${state.players.length}/7。GMの開始をお待ちください。</p>`); if (state.phase === 'INTRODUCTION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + introductionHtml(); return; } if (state.phase === 'GAME_GUIDE') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + gameGuideHtml(); return; } if (state.phase === 'STATION_INTRODUCTION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + stationIntroductionHtml(); return; } if (state.phase === 'SELF_INTRODUCTION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + selfIntroductionHtml(me.participantId); bindPlayer(); return; } if (state.phase === 'PACK_SELECTION') return renderPackSelection(me, false); if (state.phase === 'STATION_RESULT') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + stationResultHtml(); return; } if (state.phase === 'REWARD_NARRATION') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + rewardNarrationHtml(); return; } if (state.phase === 'CURRENCY_SYNC_WAIT') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + currencySyncWaitHtml(me); return; } if (state.phase === 'FREE_TIME_INTRO') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + freeTimeIntroductionHtml(); return; } if (state.phase === 'FREE_TIME') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + freeTimeHtml(me); return; } if (state.phase === 'FINAL_RANKING') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + finalRankingHtml(); return; } if (state.phase === 'FINAL_ALIGNMENT') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + finalAlignmentHtml(); return; } if (state.phase === 'FINAL_JUDGMENT') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + finalJudgmentHtml(); return; } if (state.phase === 'ENDING') { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}`) + endingHtml() + playtestSurveyHtml(me); bindPlaytestSurvey(me, false); return; } renderTurnPlayer(me, false); }
function renderPlayerPreview() { const me = state.testPlayers?.find(player => player.participantId === previewParticipantId); if (!me) { previewParticipantId = null; return renderGm(); } const back = '<button id="previewBack" class="secondary preview-back">← GM画面へ戻る</button>'; if (state.phase === 'INTRODUCTION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + introductionHtml(); else if (state.phase === 'GAME_GUIDE') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + gameGuideHtml(); else if (state.phase === 'STATION_INTRODUCTION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + stationIntroductionHtml(); else if (state.phase === 'SELF_INTRODUCTION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + selfIntroductionHtml(me.participantId); else if (state.phase === 'PACK_SELECTION') { renderPackSelection(me, true); app.insertAdjacentHTML('afterbegin', back); } else if (state.phase === 'LOBBY') app.innerHTML = back + '<section class="panel"><h2>乗車待機中</h2></section>'; else if (state.phase === 'STATION_RESULT') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + stationResultHtml(); else if (state.phase === 'REWARD_NARRATION') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + rewardNarrationHtml(); else if (state.phase === 'CURRENCY_SYNC_WAIT') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + currencySyncWaitHtml(me); else if (state.phase === 'FREE_TIME_INTRO') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + freeTimeIntroductionHtml(); else if (state.phase === 'FREE_TIME') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + freeTimeHtml(me); else if (state.phase === 'FINAL_RANKING') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + finalRankingHtml(); else if (state.phase === 'FINAL_ALIGNMENT') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + finalAlignmentHtml(); else if (state.phase === 'FINAL_JUDGMENT') app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + finalJudgmentHtml(); else if (state.phase === 'ENDING') { app.innerHTML = back + gameHeaderHtml(`PL${me.playerNumber} TEST VIEW`) + endingHtml() + playtestSurveyHtml(me); bindPlaytestSurvey(me, true); } else { renderTurnPlayer(me, true); app.insertAdjacentHTML('afterbegin', back); } bindPreview(me); }
function renderSimple(content) { app.innerHTML = `<section class="panel welcome">${content}</section>`; }

function renderPackSelection(me, preview) { app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}${preview ? ' TEST VIEW' : ''}`) + packSelectionHtml(me, preview); bindPack(me, preview); }
function packSelectionHtml(me, preview) { const pack = state.packs.find(item => item.id === me.packId); const confirmed = mePublic(me.participantId)?.confirmed; const unselected = state.players.filter(player => !player.packId).map(player => `PL${player.playerNumber}`).join('、') || 'なし'; return `<section class="focus-panel"><span class="step-label">現在の操作</span><h2>カードパックを選択</h2><p>選択中：<b>${esc(pack?.name || '未選択')}</b>${confirmed ? '（確定済み）' : ''}</p><p class="meta">ほかのPLと同じパックも選択できます。全員確定後、7種類が重複していない場合にゲームを開始できます。</p><p class="pack-unselected">未選択：${esc(unselected)}</p><div class="pack-grid">${state.packs.map(item => { const selectors = state.players.filter(player => player.packId === item.id); return `<article class="choice-card ${me.packId === item.id ? 'selected' : ''} ${selectors.length > 1 ? 'duplicated' : ''}"><span class="category">${esc(item.specialty)}</span><h3>${esc(item.name)}</h3><div class="pack-selectors">${selectors.length ? selectors.map(player => `<span class="pill ${player.confirmed ? 'confirmed' : 'pending'}">PL${player.playerNumber} ${esc(player.name)}${player.confirmed ? ' ✓' : ''}</span>`).join('') : '<span>選択者なし</span>'}</div><button data-pack-choice="${item.id}" ${confirmed ? 'disabled' : ''}>${me.packId === item.id ? '選択中' : '選択する'}</button></article>`; }).join('')}</div><div class="actions">${me.packId ? '<button type="button" id="packClear" class="secondary">選択を解除</button>' : ''}<button id="packConfirm" class="primary-action" ${!me.packId || confirmed || preview ? 'disabled' : ''}>このパックで最終確認</button></div></section>`; }

function renderTurnPlayer(me, preview) { const publicMe = mePublic(me.participantId); app.innerHTML = gameHeaderHtml(`PL${me.playerNumber}${preview ? ' TEST VIEW' : ''}`) + (state.phase === 'TURN_RESULT' ? turnResultHtml(me) : publicMe.confirmed ? waitingHtml(me) : selectionWorkspaceHtml(me)); bindTurn(me, preview); }
function selectionWorkspaceHtml(me) { const publicMe = mePublic(me.participantId); const selected = publicMe.selection; return `<div class="play-layout"><aside class="side-column"><section class="panel compact-panel"><h2>他のPL</h2>${otherPlayersHtml(me.participantId)}</section><section class="status-card"><span>YOUR STATUS</span><h2>PL${me.playerNumber} ${esc(me.name)}</h2><div class="hp-large"><small>HP</small>${me.hp}<em>/ 15</em></div>${publicMe.isDeadState ? '<div class="dead-banner">亡者状態</div>' : '<div class="alive-banner">通常状態</div>'}<p class="meta">パック：${esc(state.packs.find(pack => pack.id === me.packId)?.name || '未選択')}</p></section>${infoShopControlsHtml(me)}${me.shopInventory?.length ? shopInventoryHtml(me) : ''}</aside><main class="action-column"><section class="focus-panel"><span class="eyebrow">CURRENT ACTION</span><h2>${selected ? '対象を確認して最終確定' : '使用するカードを選択'}</h2>${stepsHtml(Boolean(selected), false)}<div class="card-hand">${me.cards.map(card => cardHtml(card, selected?.cardId === card.id, me)).join('')}</div>${selected ? selectionFormHtml(me, selected) : ''}</section></main></div>`; }
function stepsHtml(hasCard, confirmed) { return `<ol class="steps"><li class="${!hasCard ? 'active' : 'done'}"><b>1</b><span>カード選択</span></li><li class="${hasCard && !confirmed ? 'active' : confirmed ? 'done' : ''}"><b>2</b><span>対象選択</span></li><li class="${confirmed ? 'done' : hasCard ? 'active' : ''}"><b>3</b><span>最終確認</span></li></ol>`; }
function cardAvailability(card, me) {
  const extensionUntil = Number(me.cardMarks?.[card.id]?.cooldownExtensionUntil || 0);
  if (card.cooldownStatus === 'EXTENSION') {
    const remaining = Math.max(1, extensionUntil - state.globalTurnIndex + 1);
    return { unavailable: true, label: `強奪：あと${remaining}ターン使用不可`, reason: `【強奪】の効果により、あと${remaining}ターン使用できません。` };
  }
  if (card.cooldownStatus === 'NORMAL') {
    const reason = '前のターンに使用したため、このターンは使用できません。';
    return { unavailable: !card.bypassOptions?.length, label: card.bypassOptions?.length ? 'クールタイム：あと1ターン（CT無視可）' : 'クールタイム：あと1ターン', reason };
  }
  if (card.unavailableReason) return { unavailable: true, label: '使用不可', reason: card.id === 'encore' ? '再演できる使用履歴がありません。' : playerFacingText(card.unavailableReason) };
  return { unavailable: false, label: '使用可能', reason: null };
}
function cardHtml(card, selected, me) { const availability = cardAvailability(card, me); return `<article class="game-card ${card.category} ${selected ? 'selected' : ''} ${availability.unavailable ? 'unavailable' : ''}" tabindex="0"><div class="card-top"><span class="category ${card.category}">${esc(categoryName(card.category))}</span><span class="availability">${esc(availability.label)}</span></div><h3>${esc(card.name)}</h3><p>${esc(playerFacingText(card.description))}</p>${availability.unavailable ? `<button disabled>使用できません</button><details><summary>使用不能理由</summary><p class="pending">${esc(availability.reason)}</p></details>` : `<button data-card="${card.id}">${selected ? '選択中' : card.cooldownStatus === 'NORMAL' ? 'CT無視を使って選択' : 'このカードを選択'}</button>`}</article>`; }
function availableNormalShopEntries(me) { return (me.shopInventory || []).filter(entry => entry.item?.timing !== 'info' && !shopAvailability(entry).unavailable); }
function infoShopControlsHtml(me) { const entries = (me.shopInventory || []).filter(entry => entry.item?.timing === 'info'); if (!entries.length) return ''; const players = state.players.filter(player => player.participantId !== me.participantId); const alreadyUsed = Boolean(me.immediateShopUse); return `<section class="panel info-shop-controls"><span class="eyebrow">INFORMATION SHOP</span><h3>情報系SHOP</h3><p class="meta">使用した時点で、このターンのSHOP使用枠を消費します。確認後の取消はできません。</p>${entries.map(entry => { const availability = shopAvailability(entry); return `<article class="owned-shop-card ${availability.unavailable || alreadyUsed ? 'used' : ''}"><div class="owned-shop-card-top"><span>SHOP CARD</span><em>${availability.unavailable ? esc(availability.label) : alreadyUsed ? 'このターンは使用済み' : '使用可能'}</em></div><h4>${esc(entry.item.name)}</h4><p>${esc(entry.item.effect)}</p><label>確認するPL<select data-info-shop-target="${entry.inventoryId}" ${availability.unavailable || alreadyUsed ? 'disabled' : ''}>${players.map(player => `<option value="${player.participantId}">PL${player.playerNumber} ${esc(player.name)}</option>`).join('')}</select></label><button data-use-info-shop="${entry.inventoryId}" ${availability.unavailable || alreadyUsed ? 'disabled' : ''}>情報を確認する</button></article>`; }).join('')}${me.infoShopResults?.length ? `<details><summary>今回までの情報確認結果</summary>${me.infoShopResults.slice().reverse().map(result => `<p>${esc(result.result)}</p>`).join('')}</details>` : ''}</section>`; }
function shopSelectionControlHtml(me, selected) {
  const immediateUsed = Boolean(me.immediateShopUse);
  const selectedCard = me.cards.find(card => card.id === selected.cardId);
  const entries = (immediateUsed ? [] : availableNormalShopEntries(me)).filter(entry => entry.item?.effectType !== 'PREVENT_TARGET_CHANGE_ONCE_ATTACK' || selectedCard?.category === 'attack');
  const current = selected.shopEntryId || '';
  const selectedEntry = entries.find(entry => entry.inventoryId === current) || (me.shopInventory || []).find(entry => entry.inventoryId === current);
  const playerTargets = state.players.filter(player => player.participantId !== me.participantId);
  const ownNonAttackCards = me.cards.filter(card => card.category !== 'attack');
  const targetSelect = label => `<label>${label}<select id="shopTarget">${playerTargets.map(player => `<option value="${player.participantId}" ${selected.shopTargetId === player.participantId ? 'selected' : ''}>PL${player.playerNumber} ${esc(player.name)}</option>`).join('')}</select></label>`;
  let extra = '';
  if (selectedEntry?.item?.effectType === 'GRUDGE') extra = `${targetSelect('怨返しする相手')}<p class="meta">指定PLから直接実ダメージを受けた場合だけ、処理後にHP−1を返します。</p>`;
  if (selectedEntry?.item?.effectType === 'SECRET_TARGET_NOTICE') extra = targetSelect('秘密に通知する相手');
  if (selectedEntry?.item?.effectType === 'ALLY_DIRECT_REDUCTION') extra = `${targetSelect('守るプレイヤーを選択してください')}<p class="meta">このターン、指定PLが受ける直接ダメージを合計1軽減します。</p>`;
  if (selectedEntry?.item?.effectType === 'GREEDY_TICKET') extra = `<label>予約する自分のカード<select id="shopCardTarget">${ownNonAttackCards.map(card => `<option value="${card.id}" ${selected.shopCardTargetId === card.id ? 'selected' : ''}>${esc(card.name)}</option>`).join('')}</select></label>`;
  const selectedTarget = selectedEntry?.item?.effectType === 'ALLY_DIRECT_REDUCTION' && selected.shopTargetId ? `　対象：<b>${esc(playerName(selected.shopTargetId))}</b>` : '';
  const selectedText = selectedEntry ? `<p class="meta">選択中：<b>${esc(selectedEntry.item.name)}</b>${selectedTarget}</p>` : '';
  const unavailableNote = immediateUsed ? '<p class="meta">このターンは情報系SHOPカードを使用済みです。</p>' : '';
  const attackOnlyNote = selectedCard?.category !== 'attack' && (me.shopInventory || []).some(entry => entry.item?.effectType === 'PREVENT_TARGET_CHANGE_ONCE_ATTACK') ? '<p class="meta">【地獄の鎖】は攻撃カードを選んだときだけ使用できます。</p>' : '';
  return `<section class="shop-turn-choice"><label>SHOPカード（任意・1ターン最大1枚）<select id="shopEntry" ${immediateUsed ? 'disabled' : ''}><option value="">使用しない</option>${entries.map(entry => `<option value="${entry.inventoryId}" ${current === entry.inventoryId ? 'selected' : ''}>${esc(entry.item.name)} — ${esc(entry.item.effect)}</option>`).join('')}</select></label>${unavailableNote}${attackOnlyNote}${selectedText}${extra}</section>`;
}
function selectionFormHtml(me, selected) { const card = me.cards.find(item => item.id === selected.cardId); const targets = state.players.filter(player => player.participantId !== me.participantId); let control = ''; if (card.targetType === 'player') control = `<label>STEP 2　対象<select id="target">${targets.map(player => `<option value="${player.participantId}" ${selected.targetId === player.participantId ? 'selected' : ''}>PL${player.playerNumber} ${esc(player.name)}（HP ${player.hp}）</option>`).join('')}</select></label>`; else if (card.targetType.includes('Card')) { const candidates = me.cards.filter(item => item.id !== card.id && (card.targetType === 'ownAttackCard' ? item.category === 'attack' : item.category !== 'attack')); control = `<label>STEP 2　指定カード<select id="cardTarget">${candidates.map(item => `<option value="${item.id}" ${selected.cardTargetId === item.id ? 'selected' : ''}>${esc(item.name)}</option>`).join('')}</select></label>`; } else control = '<p class="step-note">STEP 2　対象選択はありません。</p>'; const targetStates = ['thaw','regression'].includes(card.id) ? (state.players.find(player => player.participantId === selected.targetId)?.ongoingEffects || []) : []; const stateControl = targetStates.length ? `<label>解除する持越状態<select id="stateKey">${targetStates.map(effect => `<option value="${effect.stackKey}" ${selected.stateKey === effect.stackKey ? 'selected' : ''}>${esc(statusDisplayName(effect.stackKey))}（値 ${effect.value}）</option>`).join('')}</select></label>` : ''; const encoreControl = card.id === 'encore' ? `<label>再演元<select id="copyUsage">${me.encoreCandidates.map(candidate => `<option value="${candidate.id}" ${selected.copyUsageId === candidate.id ? 'selected' : ''}>${esc(candidate.cardName)}（${esc(categoryName(candidate.kind === 'heal' ? 'heal' : candidate.kind === 'defense' ? 'defense' : 'attack'))}）</option>`).join('')}</select></label>` : ''; const bypassControl = card.cooldownStatus === 'NORMAL' && card.bypassOptions?.length ? `<label>CT無視手段<select id="ctBypass"><option value="">選択してください</option>${card.bypassOptions.map(option => `<option value="${option}" ${selected.ctBypass === option ? 'selected' : ''}>${({DESIRE:'欲印',GREEDY_TICKET:'欲張り札',HUNGER:'餓鬼地獄・強欲',HELL_KEY:'地獄の鍵'}[option])}</option>`).join('')}</select></label>` : ''; return `<section class="confirm-panel"><h3>選択内容</h3><div class="selection-summary"><b>${esc(card.name)}</b><span>${selected.targetId ? playerName(selected.targetId) : selected.cardTargetId ? cardName(selected.cardTargetId) : '対象なし'}</span></div>${control}${stateControl}${encoreControl}${bypassControl}${shopSelectionControlHtml(me, selected)}<button id="confirm" class="primary-action">STEP 3　この内容で最終確認</button></section>`; }
function waitingHtml(me) { const selected = mePublic(me.participantId).selection; const confirmed = state.players.filter(player => player.confirmed).length; const shopEntry = me.shopInventory?.find(entry => entry.inventoryId === selected?.shopEntryId); const shopTarget = shopEntry?.item?.effectType === 'ALLY_DIRECT_REDUCTION' && selected?.shopTargetId ? playerName(selected.shopTargetId) : null; return `<div class="waiting-layout"><section class="focus-panel waiting"><span class="eyebrow">WAITING</span><h2>最終確認済み</h2>${stepsHtml(true, true)}<div class="waiting-selection"><div><span>選択カード</span><b>${esc(cardName(selected?.cardId))}</b></div><div><span>対象</span><b>${selected?.targetId ? esc(playerName(selected.targetId)) : selected?.cardTargetId ? esc(cardName(selected.cardTargetId)) : 'なし'}</b></div>${shopEntry ? `<div><span>SHOP</span><b>${esc(shopEntry.item.name)}${shopTarget ? `（対象：${esc(shopTarget)}）` : ''}</b></div>` : ''}</div><div class="confirm-count"><strong>${confirmed} / 7</strong><span>全体の確定人数</span></div><p>一斉公開までお待ちください。</p></section><aside class="side-column"><section class="panel compact-panel"><h2>他のPL</h2>${otherPlayersHtml(me.participantId)}</section>${me.shopInventory?.length ? shopInventoryHtml(me) : ''}</aside></div>`; }
function stationResultHtml() { return `<section class="focus-panel station-result"><span class="eyebrow">STATION RESULT</span><h2>${esc(state.station?.name || '駅')} 終了</h2><p>駅結果を確定しました。これから小鬼による報酬発表を行います。</p><p class="meta">順位、報酬、隠し特殊条件と達成者は、読み上げで順に公開されます。</p></section>`; }
function shopAvailability(entry) { return entry.cooldownStatus === 'NORMAL' ? { unavailable: true, label: 'クールタイム：このターン使用不可', reason: entry.unavailableReason || '前のターンに使用したため、このターンは使用できません。' } : { unavailable: false, label: '使用可能', reason: null }; }
function shopInventoryHtml(me) { const entries = [...(me.shopInventory || [])].sort((a, b) => String(a.acquiredAt || '').localeCompare(String(b.acquiredAt || ''))); const card = entry => { const availability = shopAvailability(entry); return `<article class="owned-shop-card ${availability.unavailable ? 'used' : ''}"><div class="owned-shop-card-top"><span>SHOP CARD</span><em>${esc(availability.label)}</em></div><h4>${esc(entry.item.name)}</h4><p>${esc(playerFacingText(entry.item.effect))}</p><small>使用回数：${entry.totalUseCount || 0}回</small>${availability.unavailable ? `<details><summary>使用できない理由</summary><p class="pending">${esc(availability.reason)}</p></details>` : ''}</article>`; }; const available = entries.filter(entry => !shopAvailability(entry).unavailable); const cooling = entries.filter(entry => shopAvailability(entry).unavailable); return `<section class="panel owned-shop"><div class="owned-shop-heading"><span class="eyebrow">YOUR SHOP</span><h3>所持ショップカード</h3></div>${entries.length ? `<div class="owned-shop-groups">${available.length ? `<section><h4>使用可能</h4><div class="owned-shop-cards">${available.map(card).join('')}</div></section>` : ''}${cooling.length ? `<section><h4>クールタイム</h4><div class="owned-shop-cards">${cooling.map(card).join('')}</div></section>` : ''}</div>` : '<p class="meta">所持しているショップカードはありません。</p>'}</section>`; }
function firstShopHtml(me) {
  const shop = state.shop;
  const accepting = state.timer && Date.now() < state.timer.endsAt;
  const groups = [
    ['new', 'NEW', '今回解禁', item => item.isNew && !item.soldOut],
    ['available', '販売中', '販売継続中', item => !item.isNew && !item.soldOut],
    ['soldout', 'SOLD OUT', '売り切れ', item => item.soldOut]
  ];
  const itemHtml = (item, label) => {
    const disabled = item.soldOut || !accepting;
    const reason = item.soldOut ? 'SOLD OUT' : !accepting ? '購入受付終了' : '';
    return `<article class="shop-product ${item.soldOut ? 'sold-out' : ''}"><span class="category">${esc(label)}</span><span class="shop-origin">${esc(item.shopName)}</span><h3>${esc(item.name)}</h3><p>${esc(playerFacingText(item.effect))}</p><dl><div><dt>商品価格</dt><dd>${item.price}</dd></div><div><dt>在庫</dt><dd>${item.soldOut ? 'SOLD OUT' : '残り1'}</dd></div></dl><button data-open-shop-payment="${item.id}" data-buy-player="${me.participantId}" ${disabled ? 'disabled' : ''}>購入する</button><small class="purchase-reason">${reason}</small></article>`;
  };
  return `<section class="focus-panel shop-view"><span class="eyebrow">SHOP ${shop.currentShopId || ''}</span><h2>${esc(shop.name || 'ショップ')}</h2><p class="currency-wallet">所持冥貨：${currencySummary(me.currency)}</p><p class="meta">購入する商品を選んだ後、投入する冥貨の種類と枚数を決めます。投入額が価格を超えた分はおつりとして返ります。</p>${groups.map(([id, label, heading, predicate]) => { const items = shop.items.filter(predicate); return items.length ? `<section class="shop-group shop-group-${id}"><div class="section-heading"><h3>${heading}</h3><span>${label}</span></div><div class="shop-products">${items.map(item => itemHtml(item, label)).join('')}</div></section>` : ''; }).join('')}${shopInventoryHtml(me)}</section>`;
}
function transferHtml(me) { const types = [['one','壱'],['two','弐'],['three','参'],['five','伍'],['seven','漆']].filter(([key]) => me.currency[key] > 0); const requests = state.transferRequests || []; return `<section class="panel transfer-view"><span class="eyebrow">GM REQUEST</span><h2>GMへ冥貨を譲渡申請</h2><p class="meta">譲渡先、冥貨の種類、枚数を指定してGMへ申請します。ココフォリア上の冥貨はGMの処理後に移動します。</p>${types.length ? `<form id="transferForm"><label>譲渡先<select name="recipientId">${state.players.filter(player => player.participantId !== me.participantId).map(player => `<option value="${player.participantId}">PL${player.playerNumber} ${esc(player.name)}</option>`).join('')}</select></label><label>譲渡する冥貨<select name="currencyType">${types.map(([key,label]) => `<option value="${key}">${label}（所持 ${me.currency[key]}）</option>`).join('')}</select></label><label>枚数<input name="amount" type="number" min="1" value="1"></label><button class="primary-action" type="submit">GMへ譲渡申請</button></form>` : '<p class="meta">譲渡を申請できる冥貨を所持していません。</p>'}<div class="transfer-list"><h3>自分に関係する申請</h3>${requests.length ? requests.map(request => `<article><b>PL${request.senderNumber} → PL${request.recipientNumber}</b><span>${esc(request.currencyLabel)}×${request.amount}</span><em>${({PENDING:'GM確認待ち',CONFIRMED:request.cocofoliaApplied?'GM処理済み':'GM確定・ココフォリア未反映',REJECTED:'却下'}[request.status])}</em></article>`).join('') : '<p class="meta">譲渡申請はありません。</p>'}</div></section>`; }
function currencyHtml(me) { return `<section class="focus-panel"><span class="eyebrow">CURRENCY</span><h2>冥貨</h2><p class="currency-wallet">所持冥貨：${currencySummary(me.currency)}</p><p class="meta">譲渡はこの画面からGMへ申請してください。</p></section>${transferHtml(me)}${shopInventoryHtml(me)}`; }
function freeTimeHtml(me) { const ready = mePublic(me.participantId)?.freeTimeReady; const shopAvailable = state.shop.items.length > 0; const nav = `<nav class="free-time-nav"><button class="${freeTimeView === 'rest' ? 'active' : 'secondary'}" data-free-time-view="rest">休憩</button>${shopAvailable ? `<button class="${freeTimeView === 'shop' ? 'active' : 'secondary'}" data-free-time-view="shop">ショップ</button>` : ''}<button class="${freeTimeView === 'currency' ? 'active' : 'secondary'}" data-free-time-view="currency">冥貨</button></nav>`; if (freeTimeView === 'shop' && shopAvailable) return nav + firstShopHtml(me); if (freeTimeView === 'currency') return `${nav}${currencyHtml(me)}`; return `${nav}<section class="focus-panel waiting"><span class="eyebrow">FREE TIME</span><h2>${esc(state.station?.name || '')} 終了</h2><h3>自由時間</h3><div class="intro-timer">${timerHtml()}</div><p>${shopAvailable ? '休憩、相談、交渉、ショップ購入、冥貨の譲渡申請を行えます。' : '休憩、相談、交渉、冥貨の譲渡申請を行えます。'}</p><button id="freeTimeReady" data-ready-player="${me.participantId}" class="primary-action ${ready ? 'secondary' : ''}">${ready ? '準備完了を取り消す' : '準備完了'}</button><p class="meta">7人全員が準備完了しても自動では出発しません。</p></section>`; }
function testPlayerAction(participantId, playerAction) { return action('TEST_PLAYER_ACTION', { participantId, playerAction }); }
function shopChangeFor(value) {
  let remaining = value;
  const coins = { one: 0, two: 0, three: 0, five: 0, seven: 0 };
  for (const [type, , denomination] of [...CURRENCY_TYPES].reverse()) {
    coins[type] = Math.floor(remaining / denomination);
    remaining %= denomination;
  }
  return coins;
}

function openShopPayment(itemId, participantId) {
  const me = state.me.role === 'GM' ? state.testPlayers?.find(player => player.participantId === participantId) : state.me;
  const item = state.shop.items.find(entry => entry.id === itemId);
  if (!me || !item || item.soldOut || document.querySelector('.shop-payment-modal-backdrop')) return;
  const payment = Object.fromEntries(CURRENCY_TYPES.map(([type]) => [type, 0]));
  const controls = CURRENCY_TYPES.map(([type, label, value]) => `<article><div><b>${label}</b><span>額面 ${value}／所持 ${me.currency[type] || 0}</span></div><div class="payment-stepper"><button type="button" data-payment-adjust="${type}" data-payment-delta="-1" aria-label="${label}を1枚減らす">−</button><output data-payment-count="${type}">0</output><button type="button" data-payment-adjust="${type}" data-payment-delta="1" aria-label="${label}を1枚増やす">＋</button></div></article>`).join('');
  document.body.insertAdjacentHTML('beforeend', `<div class="result-modal-backdrop shop-payment-modal-backdrop"><section class="result-modal shop-payment-modal" role="dialog" aria-modal="true" aria-label="ショップ支払い"><span class="eyebrow">SHOP PAYMENT</span><h2>${esc(item.name)}</h2><p class="result-modal-subtitle">商品価格：${item.price}</p><p class="meta">支払いに使う冥貨の種類と枚数を選んでください。支払額は価格＋7までです。</p><div class="payment-coin-picker">${controls}</div><dl class="payment-summary"><div><dt>支払総額</dt><dd data-payment-total>0</dd></div><div><dt>予定おつり</dt><dd data-payment-change>なし</dd></div></dl><p class="payment-warning" data-payment-warning hidden>この支払いには路線図に使用できる特殊冥貨が含まれています。支払った冥貨は使用済みとなり、以後使用できません。</p><p class="purchase-reason" data-payment-reason>あと${item.price}不足しています</p><div class="actions payment-actions"><button type="button" class="secondary" data-dismiss-shop-payment>戻る</button><button type="button" class="primary-action" data-confirm-shop-payment disabled>この内容で購入</button></div></section></div>`);
  const modal = document.querySelector('.shop-payment-modal-backdrop');
  const update = () => {
    const total = CURRENCY_TYPES.reduce((sum, [type, , value]) => sum + payment[type] * value, 0);
    const specialCurrencyUsed = CURRENCY_TYPES.some(([type]) => type !== 'one' && payment[type] > 0);
    modal.querySelector('[data-payment-total]').textContent = String(total);
    modal.querySelector('[data-payment-change]').textContent = total > item.price && total <= item.price + 7 ? currencyCoinsLabel(shopChangeFor(total - item.price)) : 'なし';
    modal.querySelector('[data-payment-warning]').hidden = !specialCurrencyUsed;
    modal.querySelector('[data-payment-reason]').textContent = total < item.price ? `あと${item.price - total}不足しています` : total > item.price + 7 ? `商品価格より7までしか多く投入できません（超過 ${total - item.price - 7}）` : total === item.price ? 'ちょうどです' : `おつり：${currencyCoinsLabel(shopChangeFor(total - item.price))}`;
    modal.querySelector('[data-confirm-shop-payment]').disabled = total < item.price || total > item.price + 7;
    CURRENCY_TYPES.forEach(([type]) => {
      modal.querySelector(`[data-payment-count="${type}"]`).textContent = String(payment[type]);
      modal.querySelector(`[data-payment-adjust="${type}"][data-payment-delta="-1"]`).disabled = payment[type] === 0;
      modal.querySelector(`[data-payment-adjust="${type}"][data-payment-delta="1"]`).disabled = payment[type] >= (me.currency[type] || 0);
    });
  };
  modal.querySelectorAll('[data-payment-adjust]').forEach(button => button.addEventListener('click', () => {
    const type = button.dataset.paymentAdjust;
    payment[type] = Math.max(0, Math.min(me.currency[type] || 0, payment[type] + Number(button.dataset.paymentDelta)));
    update();
  }));
  modal.querySelector('[data-dismiss-shop-payment]').addEventListener('click', () => modal.remove());
  modal.querySelector('[data-confirm-shop-payment]').addEventListener('click', () => {
    modal.remove();
    return state.me.role === 'GM' ? testPlayerAction(participantId, { type: 'BUY_SHOP_ITEM', itemId, payment }) : action('BUY_SHOP_ITEM', { itemId, payment });
  });
  update();
}

