function renderGm() { app.innerHTML = gameHeaderHtml('GM CONTROL') + gmViewerBarHtml() + gmNavHtml() + `<section class="gm-shell">${gmTabContent()}</section>` + previewOverlayHtml(); bindGm(); document.querySelector('#playtestModeToggle')?.addEventListener('change', event => action('SET_PLAYTEST_MODE', { enabled: event.target.checked })); bindPrimaryNarrativeControls(); bindGameGuide(); addGameGuideTestOption(); bindPurchaseCurrencyReflection(); }
function gmViewerBarHtml() { return `<section class="viewer-bar"><label>ユーザー画面を見る<select id="preview"><option value="">選択してください</option>${state.players.map(player => `<option value="${player.participantId}" ${previewParticipantId === player.participantId ? 'selected' : ''}>PL${player.playerNumber} ${esc(player.name)}</option>`).join('')}</select></label><span>GM画面を残したまま確認できます</span></section>`; }
function previewOverlayHtml() { if (!previewParticipantId) return ''; const me = state.testPlayers?.find(player => player.participantId === previewParticipantId); if (!me) return ''; let content = ''; if (state.phase === 'INTRODUCTION') content = introductionHtml(); else if (state.phase === 'GAME_GUIDE') content = gameGuideHtml(); else if (state.phase === 'STATION_INTRODUCTION') content = stationIntroductionHtml(); else if (state.phase === 'SELF_INTRODUCTION') content = selfIntroductionHtml(me.participantId); else if (state.phase === 'PACK_SELECTION') content = packSelectionHtml(me, true); else if (state.phase === 'LOBBY') content = '<section class="panel"><h2>乗車待機中</h2></section>'; else if (state.phase === 'STATION_RESULT') content = stationResultHtml(); else if (state.phase === 'REWARD_NARRATION') content = rewardNarrationHtml(); else if (state.phase === 'CURRENCY_SYNC_WAIT') content = currencySyncWaitHtml(me); else if (state.phase === 'FREE_TIME_INTRO') content = freeTimeIntroductionHtml(); else if (state.phase === 'FREE_TIME') content = freeTimeHtml(me); else if (state.phase === 'FINAL_RANKING') content = finalRankingHtml(); else if (state.phase === 'FINAL_ALIGNMENT') content = finalAlignmentHtml(); else if (state.phase === 'FINAL_JUDGMENT') content = finalJudgmentHtml(); else if (state.phase === 'ENDING') content = endingHtml() + playtestSurveyHtml(me); else content = state.phase === 'TURN_RESULT' ? turnResultHtml(me) : mePublic(me.participantId).confirmed ? waitingHtml(me) : selectionWorkspaceHtml(me); return `<div class="preview-overlay" role="dialog" aria-modal="true" aria-label="PL画面プレビュー"><section class="preview-window"><header><div><span class="eyebrow">USER VIEW</span><h2>PL${me.playerNumber} ${esc(me.name)} の画面</h2></div><button id="previewClose" class="secondary">閉じる</button></header>${gameHeaderHtml(`PL${me.playerNumber} PREVIEW`)}<div class="preview-body ${state.testMode ? '' : 'read-only'}">${content}</div>${state.testMode ? '<p class="preview-note">テストルームでは、この画面からPL操作も行えます。</p>' : '<p class="preview-note">通常ルームでは閲覧専用です。</p>'}</section></div>`; }
function gmNavHtml() { const tabs = [['progress', '進行'], ['players', 'PL管理'], ['currency', '冥貨'], ['shop', 'ショップ'], ...(state.playtest?.enabled ? [['playtest', 'プレイテスト']] : []), ['test', 'テスト']]; return `<nav class="gm-tabs" aria-label="GM情報管理">${tabs.map(([id, label]) => `<button data-gm-tab="${id}" class="${gmTab === id ? 'active' : ''}" ${id === 'test' && !state.testMode ? 'disabled' : ''}>${label}</button>`).join('')}</nav>`; }
function gmTabContent() { if (gmTab === 'players') return gmPlayersPanel(); if (gmTab === 'currency') return gmCurrencyPanel(); if (gmTab === 'shop') return gmShopPanel(); if (gmTab === 'playtest' && state.playtest?.enabled) return gmPlaytestPanel(); if (gmTab === 'test') return `<section class="panel"><h2>テスト機能</h2>${testNavigationHtml()}${state.phase === 'PACK_SELECTION' ? testPackSelection() : ''}${state.testMode ? '<button id="grantCurrency" class="secondary">全PLの壱を20枚にする</button>' : ''}</section>`; return gmProgressPanel(); }
function gmCurrencySyncPanel() { const transactions = state.stationCurrencyTransactions || []; const sync = state.currencySync || { total: transactions.length, pending: transactions.filter(item => !item.cocofoliaApplied).length }; const grouped = new Map(); for (const transaction of transactions) grouped.set(transaction.participantId, [...(grouped.get(transaction.participantId) || []), transaction]); return `<section class="panel currency-sync-panel"><div class="section-heading"><h2>ココフォリア反映確認</h2><span>GM専用</span></div><div class="currency-sync-count"><strong>反映済み ${sync.total - sync.pending}件</strong><b>未反映：${sync.pending}件</b></div>${sync.pending === 0 ? '<p class="success-message">ココフォリアへの冥貨反映が完了しました。未反映：0件</p>' : '<p class="meta">ココフォリアで冥貨を渡した後、対応する報酬を反映済みにしてください。</p>'}${[...grouped.entries()].map(([participantId, entries]) => `<article class="currency-sync-player"><header><b>PL${entries[0].playerNumber} ${esc(entries[0].playerName || '')}</b>${entries.some(entry => !entry.cocofoliaApplied) ? `<button class="secondary small" data-mark-player-station-rewards="${participantId}">このPLをすべて反映済み</button>` : '<span class="pill confirmed">すべて反映済み</span>'}</header>${entries.map(entry => `<div><span>${esc(entry.label || '報酬')}　壱×${entry.amount}</span>${entry.cocofoliaApplied ? '<span class="pill confirmed">反映済み</span>' : `<button class="secondary small" data-mark-station-reward="${entry.id}">反映済み</button>`}</div>`).join('')}</article>`).join('') || '<p class="meta">今回の冥貨報酬はありません。</p>'}</section>`; }
function gmProgressPanel() { const confirmed = state.players.filter(player => player.confirmed).length; const pending = state.players.filter(player => !player.confirmed).map(player => `PL${player.playerNumber}`).join('、') || 'なし'; const duplicates = duplicatePackNames(); const resultPhase = state.phase === 'TURN_RESULT'; const pendingPurchaseCurrencies = state.purchaseTransactions?.filter(item => !item.currencyCocofoliaApplied).length || 0; const pendingTransfers = state.transferRequests?.filter(item => item.status === 'PENDING' || (item.status === 'CONFIRMED' && !item.cocofoliaApplied)).length || 0; const ready = state.players.filter(player => player.freeTimeReady).length; return `<div class="gm-progress"><section class="focus-panel gm-action"><span class="eyebrow">NEXT ACTION</span><h2>${gmInstruction()}</h2><div class="primary-control">${gmActions(confirmed)}</div>${state.phase === 'PACK_SELECTION' && duplicates.length ? `<p class="pack-warning">重複中：<b>${esc(duplicates.join('、'))}</b>　PL管理から確定を解除して選び直してください。</p>` : ''}${['PACK_SELECTION','TURN_SELECTION','TURN_RESULT'].includes(state.phase) ? `<p class="pending-list">${resultPhase ? '結果未確認' : '未確定'}PL：<b>${pending}</b></p>` : ''}${state.phase === 'FREE_TIME' ? `<p class="pending-list">準備完了：<b>${ready}/7</b></p>${pendingPurchaseCurrencies || pendingTransfers ? `<p class="pack-warning">未処理・未反映の冥貨：購入 ${pendingPurchaseCurrencies}件／譲渡 ${pendingTransfers}件</p>` : '<p class="success-message">未処理・未反映の冥貨：0件</p>'}` : ''}</section>${state.phase === 'STATION_RESULT' ? stationResultHtml() : ''}${state.phase === 'REWARD_NARRATION' ? rewardNarrationHtml() + rewardNarrationAdvanceHtml() : ''}${state.phase === 'CURRENCY_SYNC_WAIT' ? gmCurrencySyncPanel() : ''}${state.phase === 'FREE_TIME_INTRO' ? freeTimeIntroductionHtml() + freeTimeIntroductionAdvanceHtml() : ''}${state.phase === 'INTRODUCTION' ? introductionHtml() + introductionAdvanceHtml() : ''}${state.phase === 'GAME_GUIDE' ? gameGuideHtml() + gameGuideAdvanceHtml() : ''}${state.phase === 'STATION_INTRODUCTION' ? stationIntroductionHtml() + stationIntroductionAdvanceHtml() : ''}${state.phase === 'SELF_INTRODUCTION' ? selfIntroductionHtml() : ''}${state.phase === 'FINAL_RANKING' ? finalRankingHtml() : ''}${state.phase === 'FINAL_ALIGNMENT' ? finalAlignmentHtml() : ''}${state.phase === 'FINAL_JUDGMENT' ? finalJudgmentHtml() : ''}${state.phase === 'ENDING' ? endingHtml() : ''}</div>`; }
function duplicatePackNames() { const counts = new Map(); state.players.forEach(player => { if (player.packId) counts.set(player.packId, (counts.get(player.packId) || 0) + 1); }); return [...counts].filter(([, count]) => count > 1).map(([packId]) => state.packs.find(pack => pack.id === packId)?.name || packId); }
function gmInstruction() { if (state.phase === 'LOBBY') return '7人の参加後、導入を開始'; if (state.phase === 'INTRODUCTION') return '導入を読み進める'; if (state.phase === 'GAME_GUIDE') return 'ゲーム説明を読み進める'; if (state.phase === 'STATION_INTRODUCTION') return `${state.station?.name || '次の地獄'}の説明を読み進める`; if (state.phase === 'SELF_INTRODUCTION') return '全員の自己紹介完了を待つ'; if (state.phase === 'PACK_SELECTION') return '全員のパック確定を待つ'; if (state.phase === 'TURN_SELECTION') return '全員の最終確認後、一斉公開する'; if (state.phase === 'STATION_RESULT') return '駅結果を確認して報酬発表を開始'; if (state.phase === 'REWARD_NARRATION') return '小鬼による報酬発表を読み進める'; if (state.phase === 'CURRENCY_SYNC_WAIT') return 'ココフォリアへの冥貨反映を確認する'; if (state.phase === 'FREE_TIME_INTRO') return '自由時間の案内を読み進める'; if (state.phase === 'FREE_TIME') return '自由時間終了後、次の地獄へ進む'; if (state.phase === 'FINAL_RANKING') return '最終順位を確認して最終整線を開始する'; if (state.phase === 'FINAL_ALIGNMENT') return '最終整線の終了後、GM最終判定へ進む'; if (state.phase === 'FINAL_JUDGMENT') return '盤面を非公開で判定してエンディングを確定する'; if (state.phase === 'ENDING') return 'エンディングを公開する'; return '結果確認後、次のターンへ進む'; }
function gmPlayersPanel() { return `<section class="panel"><div class="section-heading"><h2>PL管理</h2><span>HP補正・確定解除</span></div>${gmStatusTable(true)}</section>`; }
function gmCooldownHtml(playerId) { const holder = state.testPlayers?.find(player => player.participantId === playerId); const blockedCards = holder?.cards?.filter(card => ['EXTENSION', 'NORMAL'].includes(card.cooldownStatus)) || []; if (!blockedCards.length) return ''; return `<div class="gm-cooldown"><small>使用制限</small>${blockedCards.map(card => `<span>${esc(card.name)}：${esc(cardAvailability(card, holder).label)}</span>`).join('')}</div>`; }
function gmChoiceHtml(player) { const cooldown = gmCooldownHtml(player.participantId); if (state.phase === 'PACK_SELECTION') { const pack = state.packs.find(item => item.id === player.packId); return `<div class="gm-choice"><small>選択パック</small><b>${esc(pack?.name || '未選択')}</b>${cooldown}</div>`; } if (state.phase === 'TURN_SELECTION') { const selection = player.selection; if (!selection) return `<div class="gm-choice"><small>今回の選択</small><b>未選択</b>${cooldown}</div>`; const card = state.packs.flatMap(pack => pack.cards || []).find(item => item.id === selection.cardId); const target = state.players.find(item => item.participantId === selection.targetId); return `<div class="gm-choice"><small>今回の選択</small><b>${esc(card?.name || selection.cardId)}</b><span>対象：${esc(target ? `PL${target.playerNumber} ${target.name}` : '対象なし')}</span>${cooldown}</div>`; } return cooldown ? `<div class="gm-choice">${cooldown}</div>` : '<div class="gm-choice"></div>'; }
function gmStatusTable(manage) { const resultPhase = state.phase === 'TURN_RESULT'; return `<div class="gm-player-table">${state.players.map(player => `<article><div class="player-id"><span>PL${player.playerNumber}</span><b>${esc(player.name)}</b></div>${gmChoiceHtml(player)}<strong class="mini-hp">HP ${player.hp}</strong>${player.isDeadState ? '<span class="pill dead">亡者</span>' : '<span class="pill alive">通常</span>'}<span class="pill ${player.confirmed ? 'confirmed' : 'pending'}">${player.confirmed ? (resultPhase ? '確認済み' : '確定') : (resultPhase ? '未確認' : '未確定')}</span>${manage ? `<div class="row-actions">${player.confirmed && !resultPhase ? `<button class="secondary small" data-unlock="${player.participantId}">確定解除</button>` : ''}<button class="secondary small" data-hp="${player.participantId}" data-current="${player.hp}">HP補正</button></div>` : ''}</article>`).join('')}</div>`; }
function gmCurrencyPanel() { const transfers = state.transferRequests || []; return `<section class="panel"><div class="section-heading"><h2>冥貨・所持SHOP</h2><span>GM専用</span></div><div class="currency-grid">${state.testPlayers?.map(player => `<article><b>PL${player.playerNumber} ${esc(player.name)}</b><p>${currencySummary(player.currency)}</p><small>所持SHOP：${player.shopInventory.length ? player.shopInventory.map(entry => esc(entry.item.name)).join('、') : 'なし'}</small></article>`).join('') || '<p>冥貨の詳細はGM専用情報です。</p>'}</div><div class="transfer-admin"><h2>GMによる譲渡処理</h2><p class="meta">PLの申請を確認してWeb上の譲渡を確定し、ココフォリアで冥貨を移動した後に処理済みをチェックします。</p>${transfers.length ? transfers.map(request => `<article><div><b>PL${request.senderNumber} ${esc(request.senderName)} → PL${request.recipientNumber} ${esc(request.recipientName)}</b><p>${esc(request.currencyLabel)}×${request.amount}</p></div><span class="pill ${request.status === 'CONFIRMED' ? 'confirmed' : 'pending'}">${request.status === 'PENDING' ? 'GM確認待ち' : request.status === 'REJECTED' ? '却下' : request.cocofoliaApplied ? 'GM処理済み' : 'GM確定・ココフォリア未反映'}</span>${request.status === 'PENDING' ? `<div class="row-actions"><button data-approve-transfer="${request.id}">譲渡を確定</button><button class="secondary" data-reject-transfer="${request.id}">却下</button></div>` : request.status === 'CONFIRMED' && !request.cocofoliaApplied ? `<button class="secondary" data-mark-transfer="${request.id}">ココフォリアで処理済み ✓</button>` : ''}</article>`).join('') : '<p class="meta">譲渡申請はありません。</p>'}</div></section>`; }
function gmShopPanel() { const transactions = state.purchaseTransactions || []; return `<section class="panel"><div class="section-heading"><h2>${esc(state.shop.name || 'ショップ管理')}</h2><span>SHOPはWeb管理</span></div><p class="meta">PLが選んだ冥貨を受け取り、超過分のおつりを渡します。ココフォリアで反映するのは冥貨だけです。</p><div class="shop-stock-summary">${state.shop.items.map(item => `<span>${esc(item.name)}：${item.soldOut ? 'SOLD OUT' : '在庫1'}</span>`).join('') || '<span>現在はショップを開いていません。</span>'}</div><div class="purchase-transactions">${transactions.length ? transactions.map(transaction => `<article><div><b>PL${transaction.playerNumber} ${esc(transaction.playerName)}</b><strong>${esc(transaction.itemName)}購入</strong></div><p>ココフォリア冥貨：${esc(currencyCoinsLabel(transaction.payment))}を使用<br>おつり：${esc(transaction.change.label)}</p><span class="pill ${transaction.currencyCocofoliaApplied ? 'confirmed' : 'pending'}">冥貨：${transaction.currencyCocofoliaApplied ? '反映済み' : '未反映'}</span>${transaction.currencyCocofoliaApplied ? '' : `<button class="secondary" data-mark-purchase-currency="${transaction.id}">冥貨の反映済み</button>`}</article>`).join('') : '<p class="meta">購入取引はありません。</p>'}</div></section>`; }
const PLAYTEST_OBSERVATION_STATUS = [['UNCONFIRMED', '未確認'], ['YES', '○'], ['NO', '×'], ['NOTE', 'メモあり']];
function playtestObservationValue(id) { const value = state.playtest?.observations?.[id]; return value && typeof value === 'object' ? value : { status: value ? 'YES' : 'UNCONFIRMED', note: '' }; }
function playtestObservationGroup(title, entries) { return `<section class="playtest-observation-group"><h3>${esc(title)}</h3>${entries.map(([id, label]) => { const observation = playtestObservationValue(id); return `<article><b>${esc(label)}</b><div class="observation-statuses">${PLAYTEST_OBSERVATION_STATUS.map(([status, text]) => `<button type="button" class="secondary small ${observation.status === status ? 'active' : ''}" data-playtest-observation-status="${id}" data-status="${status}">${text}</button>`).join('')}</div><div class="observation-note"><input data-playtest-observation-note="${id}" value="${esc(observation.note || '')}" placeholder="任意メモ"><button type="button" class="secondary small" data-save-playtest-note="${id}">保存</button></div></article>`; }).join('')}</section>`; }
function surveyCards(ids) { return (ids || []).map(cardName).join('、') || 'なし'; }
function surveyShops(ids) { return (ids || []).map(id => state.shop?.items?.find(item => item.id === id)?.name || id).join('、') || 'なし'; }
function playtestExportPayload() { return { schemaVersion: 'v0.3-playtest-export', exportedAt: new Date().toISOString(), session: state.playtest?.session || null, result: state.playtest?.finalResult || null, surveys: state.playtest?.surveys || [], observations: state.playtest?.observations || {} }; }
function playtestMarkdownExport(payload) { const result = payload.result || {}; const lines = ['# 地獄廻線 プレイテスト結果', '', `- playtestId: ${payload.session?.playtestId || '—'}`, `- roomId: ${payload.session?.roomId || '—'}`, `- 実施日時: ${payload.session?.startedAt || '—'}`, `- 状態: ${payload.session?.status || 'IN_PROGRESS'}`, `- 参加人数: ${payload.session?.participantCount || 0}`, `- END: ${result.ending?.title || '未確定'}`, '', '## PL別']; for (const player of result.players || []) lines.push(`- PL${player.playerNumber}: ${player.packId} / ${player.finalRank || '—'}位 / HP ${player.finalHp} / 与${player.totalDamageDealt} 被${player.totalDamageTaken} 支援${player.totalSupport}`); lines.push('', '## GM観察'); for (const [id, observation] of Object.entries(payload.observations || {})) lines.push(`- ${id}: ${observation.status || 'UNCONFIRMED'}${observation.note ? ` — ${observation.note}` : ''}`); lines.push('', '## アンケート'); for (const survey of payload.surveys || []) lines.push(`- PL${survey.playerNumber}: ${survey.answers ? `楽しさ ${survey.answers.packFun || '—'} / 強さ ${survey.answers.packStrength || '—'}` : '未回答'}`); return lines.join('\n'); }
function exportPlaytest(format) { const payload = playtestExportPayload(); const content = format === 'markdown' ? playtestMarkdownExport(payload) : JSON.stringify(payload, null, 2); const blob = new Blob([content], { type: format === 'markdown' ? 'text/markdown;charset=utf-8' : 'application/json;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `jigoku-kaisen-playtest-${payload.session?.playtestId || 'result'}.${format === 'markdown' ? 'md' : 'json'}`; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(link.href), 0); }
function gmPlaytestPanel() {
  const result = state.playtest?.finalResult;
  const surveys = state.playtest?.surveys || [];
  const observationHtml = `<section class="panel playtest-observations"><div class="section-heading"><h2>GM観察メモ</h2><span>プレイテスト専用</span></div><p class="meta">1クリックで未確認・○・×・メモありを記録できます。任意メモは短文だけで構いません。数値や進行には影響しません。</p>${playtestObservationGroup('血の池', [['blood_heal_wanted', '回復を使いたがった'], ['blood_healing_helps_opponents', '回復すると相手が有利だと感じていた'], ['blood_transfusion_cost_concern', '輸血HP−1を嫌がった'], ['blood_vampire_overused', '吸血中心になった'], ['blood_support_rank_concern', '支援点を意識していた']])}${playtestObservationGroup('第六SHOP', [['shop6_enma_wanted', '閻魔の眼を欲しがった'], ['shop6_chain_wanted', '六道の鎖を欲しがった'], ['shop6_infinite_wanted', '無間の札を欲しがった'], ['shop6_effect_unclear', '効果を理解できなかった'], ['shop6_late_purchase_comment', '残り5ターンだから見送った'], ['shop6_currency_saved', '冥貨を残したくて見送った']])}${playtestObservationGroup('冥貨・路線図', [['currency_prime_notice', '素数額面に気づいた'], ['currency_reverse_notice', '裏面を確認した'], ['currency_rail_notice', '線路だと気づいた'], ['currency_consulted_players', '他PLへ相談した'], ['currency_save_discussion', '支払いより保持を優先した'], ['currency_heaven_line_timing', '天国線を組み始めた']])}</section>`;
  if (!result) return `${observationHtml}<section class="panel empty-state"><span class="eyebrow">PLAYTEST RESULT</span><h2>ゲーム終了後に集計します</h2><p>エンディング確定時に、カード・SHOP・冥貨・順位の履歴を自動保存します。</p><button type="button" class="secondary" id="markPlaytestInterrupted">この卓を中断として記録する</button><p class="meta">ゲーム進行や数値は変えず、ここまでの記録だけをGM用に保存します。</p></section>`;
  const playerRows = result.players.map(player => `<article><b>PL${player.playerNumber} ${esc(player.name)}</b><span>${esc(state.packs.find(pack => pack.id === player.packId)?.name || player.packId)}</span><span>${player.finalRank || '—'}位 / HP ${player.finalHp}</span><span>与 ${player.totalDamageDealt}・被 ${player.totalDamageTaken}・支援 ${player.totalSupport}</span><span>SHOP 購入${player.purchasedShopIds.length} / 使用${player.shopUseCount}</span><small>HP0：${player.deadStations.join('、') || 'なし'}<br>七獄カード：${player.sevenCardUsage.map(use => cardName(use.cardId)).join('、') || 'なし'}</small></article>`).join('');
  const packRows = result.comparison?.packs?.map(pack => `<tr><th>${esc(state.packs.find(item => item.id === pack.packId)?.name || pack.packId)}</th><td>${pack.useCount}</td><td>${pack.averageFinalRank?.toFixed(2) ?? '—'}</td><td>${pack.averageFinalHp?.toFixed(2) ?? '—'}</td><td>${pack.averageFun?.toFixed(2) ?? '—'}</td><td>${pack.averageStrength?.toFixed(2) ?? '—'}</td></tr>`).join('') || '';
  const shopRows = result.comparison?.shops?.map(shop => `<tr><th>${esc(result.shops.find(item => item.itemId === shop.itemId)?.name || shop.itemId)}</th><td>${shop.purchaseCount}</td><td>${shop.useCount}</td><td>${shop.worthwhileVotes}</td><td>${shop.wantedVotes}</td></tr>`).join('') || '';
  const surveyRows = surveys.map(entry => { const answer = entry.answers; return `<article><b>PL${entry.playerNumber} ${esc(entry.name)}</b>${answer ? `<span>楽しさ ${answer.packFun || '—'} / 強さ ${answer.packStrength || '—'}</span><span>使いにくい：${esc(surveyCards(answer.difficultCardIds))}</span><span>強すぎる：${esc(surveyCards(answer.strongCardIds))}</span><span>買ってよかった：${esc(surveyShops(answer.worthwhileShopIds))}</span><span>欲しかったSHOP：${esc(surveyShops(answer.wantedShopIds))}</span>${entry.packId === 'blood' ? `<span>血の池方針：${esc({ ATTACK_ABSORB:'攻撃・吸収', HEAL_SUPPORT:'回復・支援', INTERFERENCE:'妨害', DEFENSE_REFLECTION:'防御・反射', BALANCED:'バランス型' }[answer.blood?.focus] || '未回答')}</span>` : ''}<small>${esc(answer.comments || answer.difficultText || answer.strongText || '自由記述なし')}</small>` : '<span class="meta">未回答</span>'}</article>`; }).join('');
  const currencyRows = result.currencyTimeline.map(row => `<article><b>PL${state.players.find(player => player.participantId === row.participantId)?.playerNumber || '?'} </b><span>弐 ${row.discoveries.two?.at || '未取得'} / 参 ${row.discoveries.three?.at || '未取得'} / 伍 ${row.discoveries.five?.at || '未取得'} / 漆 ${row.discoveries.seven?.at || '未取得'}</span><small>特殊冥貨での支払い：${row.specialCoinPayments.length}回 / 最終所持：${currencySummary(row.finalHoldings)}</small></article>`).join('');
  const session = state.playtest?.session || {};
  return `${observationHtml}<section class="panel playtest-results"><div class="section-heading"><h2>プレイテスト結果</h2><span>${esc(result.ending?.title || '')}</span></div><p class="meta">${esc(session.startedAt || '—')} 実施 / ${esc(session.status || 'COMPLETED')} / ${session.participantCount || 0}人 / Playtest ${esc(session.playtestId || '—')}</p><div class="actions"><button type="button" class="secondary" data-export-playtest="json">JSONを保存</button><button type="button" class="secondary" data-export-playtest="markdown">Markdownを保存</button></div><p class="meta">エクスポートにはGM専用の結果・アンケート・観察メモを含みます。3卓比較用の固定スキーマもJSONに含まれます。</p><h3>PL別</h3><div class="playtest-player-results">${playerRows}</div><h3>パック別（比較用）</h3><table><thead><tr><th>パック</th><th>使用</th><th>平均順位</th><th>平均最終HP</th><th>楽しさ</th><th>強さ</th></tr></thead><tbody>${packRows}</tbody></table><h3>SHOP別（比較用）</h3><table><thead><tr><th>SHOP</th><th>購入</th><th>使用</th><th>買ってよかった</th><th>欲しかった</th></tr></thead><tbody>${shopRows}</tbody></table><h3>冥貨の取得・再支払い</h3><div class="playtest-survey-results">${currencyRows}</div><h3>アンケート</h3><div class="playtest-survey-results">${surveyRows}</div></section>`;
}
function placeholderPanel(title, text) { return `<section class="panel empty-state"><span class="eyebrow">${esc(title)}</span><h2>準備中</h2><p>${esc(text)}</p></section>`; }
function gmActions(confirmed) { const nextStation = state.stations[state.stations.findIndex(item => item.id === state.station?.id) + 1]; if (state.phase === 'LOBBY') return `<label class="playtest-toggle"><input id="playtestModeToggle" type="checkbox" ${state.playtestMode ? 'checked' : ''}> プレイテスト記録を有効にする</label><button id="openIntro" class="primary-action" ${state.players.length !== 7 ? 'disabled' : ''}>導入を開始</button>`; if (state.phase === 'INTRODUCTION') return '<p>画面下の「次へ」で導入を進めてください。</p>'; if (state.phase === 'GAME_GUIDE') return '<p>画面下の「次へ」でゲーム説明を進めてください。</p>'; if (state.phase === 'STATION_INTRODUCTION') return `<p>画面下の「次へ」で${esc(state.station?.name || '次の地獄')}の説明を進めてください。</p>`; if (state.phase === 'SELF_INTRODUCTION') { const allDone = state.players.every(player => player.selfIntroductionComplete); const timeUp = Date.now() >= state.timer.endsAt; return `<button id="openGameGuide" class="primary-action" ${allDone || timeUp ? '' : 'disabled'}>${allDone && !timeUp ? '全員完了：ゲーム説明へ' : 'ゲーム説明へ進む'}</button>`; } if (state.phase === 'PACK_SELECTION') { const unique = state.players.every(player => player.packId) && new Set(state.players.map(player => player.packId)).size === 7; return `<button id="start" class="primary-action" ${confirmed === 7 && unique ? '' : 'disabled'}>第一・焦熱地獄を開始</button>`; } if (state.phase === 'TURN_SELECTION') return `<button id="reveal" class="primary-action" ${confirmed !== 7 ? 'disabled' : ''}>一斉公開して処理</button>`; if (state.phase === 'STATION_RESULT') return '<button id="startRewardNarration" class="primary-action">報酬発表を開始</button>'; if (state.phase === 'REWARD_NARRATION') return '<p>画面下の「次へ」で報酬発表を進めてください。</p>'; if (state.phase === 'CURRENCY_SYNC_WAIT') return `<button id="startFreeTime" class="primary-action">自由時間を開始する</button>`; if (state.phase === 'FREE_TIME_INTRO') return '<p>画面下の「次へ」で自由時間の案内を進めてください。</p>'; if (state.phase === 'FREE_TIME') return `<button id="startNextStation" class="primary-action" ${nextStation ? '' : 'disabled'}>${nextStation ? `${esc(nextStation.name)}へ` : '次の地獄はありません'}</button>`; if (state.phase === 'FINAL_RANKING') return '<button id="startFinalAlignment" class="primary-action">最終整線を開始（3分）</button>'; if (state.phase === 'FINAL_ALIGNMENT') return '<button id="startFinalJudgment" class="primary-action">最終整線を終了してGM判定へ</button>'; if (state.phase === 'FINAL_JUDGMENT') return '<div class="actions"><button class="secondary" data-final-ending="HEAVEN_BOUND">天国行きを確定</button><button class="secondary" data-final-ending="HEAVEN_PASSING">通過する天国を確定</button><button class="primary-action" data-final-ending="HELL_LOOP">地獄廻線を確定</button></div>'; if (state.phase === 'ENDING') return '<p class="success-message">エンディングを確定しました。</p>'; return `<div class="actions">${state.testMode ? '<button id="ackAllResults" class="secondary">全PLの結果確認を一括完了</button>' : ''}<button id="next" class="primary-action" ${confirmed !== 7 ? 'disabled' : ''}>次ターンへ</button></div>`; }
function testNavigationHtml() { const fixed = [['INTRODUCTION', '導入'], ['SELF_INTRODUCTION', '自己紹介'], ['PACK_SELECTION', 'パック選択']]; const stationPhases = state.stations.flatMap((station, stationIndex) => { const turns = Array.from({ length: station.turnCount }, (_, index) => [['TURN_SELECTION', `${station.name} 第${index + 1}ターン・カード選択`], ['TURN_RESULT', `${station.name} 第${index + 1}ターン・結果`]].map(([phase, label]) => [`${phase}:${stationIndex}:${index + 1}`, label])).flat(); const stationIntro = [[`STATION_INTRODUCTION:${stationIndex}:0`, `${station.name}へ・駅導入`]]; return stationIndex < state.stations.length - 1 ? [...stationIntro, ...turns, [`FREE_TIME:${stationIndex}:0`, `${station.name}終了後・自由時間（休憩5分）`]] : [...stationIntro, ...turns]; }); const current = state.station ? `${state.phase}:${state.stations.findIndex(item => item.id === state.station.id)}:${['FREE_TIME', 'STATION_INTRODUCTION'].includes(state.phase) ? 0 : state.stationTurn}` : state.phase; return `<label>移動先<select id="testPhase">${[...fixed, ...stationPhases].map(([value, label]) => `<option value="${value}" ${value === current ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select></label><div class="actions"><button id="jumpPhase">フェーズ移動</button>${state.phase === 'PACK_SELECTION' ? '<button class="secondary" id="autofillPacks">全PLへパックを自動割り当て</button>' : ''}${state.phase === 'TURN_SELECTION' ? '<button class="secondary" id="autofill">全PLを自動選択・確定</button><button class="secondary" id="timerReset">タイマーを戻す</button>' : ''}${state.phase === 'TURN_RESULT' ? '<button class="secondary" id="ackAllResults">全PLの結果確認を一括完了</button>' : ''}</div><p class="meta">移動時は未確定の選択と公開結果を消去します。</p>`; }
function testPackSelection() { return `<details><summary>PL別パック割り当て</summary><div class="pack-admin">${state.players.map(player => `<label>PL${player.playerNumber}<select data-test-pack="${player.participantId}"><option value="">未選択</option>${state.packs.map(pack => `<option value="${pack.id}" ${player.packId === pack.id ? 'selected' : ''}>${esc(pack.name)}</option>`).join('')}</select></label>`).join('')}</div></details>`; }
function bindGm() { document.querySelectorAll('[data-gm-tab]').forEach(button => button.addEventListener('click', () => { gmTab = button.dataset.gmTab; render(); })); document.querySelector('#openIntro')?.addEventListener('click', () => action('OPEN_INTRODUCTION')); document.querySelector('#advanceIntro')?.addEventListener('click', () => action('ADVANCE_INTRODUCTION')); document.querySelector('#advanceStationIntro')?.addEventListener('click', () => action('ADVANCE_STATION_INTRODUCTION')); document.querySelector('#startRewardNarration')?.addEventListener('click', () => action('START_REWARD_NARRATION')); document.querySelector('#advanceRewardNarration')?.addEventListener('click', () => action('ADVANCE_REWARD_NARRATION')); document.querySelector('#advanceFreeTimeIntroduction')?.addEventListener('click', () => action('ADVANCE_FREE_TIME_INTRODUCTION')); document.querySelector('#openPacks')?.addEventListener('click', () => action('OPEN_PACK_SELECTION')); document.querySelector('#start')?.addEventListener('click', () => action('START_FIRST_STATION')); document.querySelector('#reveal')?.addEventListener('click', () => action('REVEAL_AND_RESOLVE')); document.querySelector('#next')?.addEventListener('click', () => action('NEXT_TURN')); document.querySelector('#startFreeTime')?.addEventListener('click', () => action('START_FREE_TIME')); document.querySelector('#startNextStation')?.addEventListener('click', () => action('START_NEXT_STATION')); document.querySelector('#startFinalAlignment')?.addEventListener('click', () => action('START_FINAL_ALIGNMENT')); document.querySelector('#startFinalJudgment')?.addEventListener('click', () => action('START_FINAL_JUDGMENT')); document.querySelectorAll('[data-final-ending]').forEach(button => button.addEventListener('click', () => action('CONFIRM_FINAL_ENDING', { endingId: button.dataset.finalEnding }))); document.querySelector('#autofillPacks')?.addEventListener('click', () => action('TEST_AUTOFILL_PACKS')); document.querySelector('#autofill')?.addEventListener('click', () => action('TEST_AUTOFILL_TURN')); document.querySelector('#ackAllResults')?.addEventListener('click', () => action('TEST_ACK_ALL_RESULTS')); document.querySelector('#grantCurrency')?.addEventListener('click', () => action('TEST_GRANT_ONE_CURRENCY')); document.querySelector('#timerReset')?.addEventListener('click', () => action('SET_TIMER', { seconds: 180 })); document.querySelector('#jumpPhase')?.addEventListener('click', () => { const [phase, stationIndex, stationTurn] = document.querySelector('#testPhase').value.split(':'); action('TEST_JUMP_PHASE', { phase, stationIndex: Number(stationIndex), stationTurn: Number(stationTurn) }); }); document.querySelectorAll('[data-mark-station-reward]').forEach(button => button.addEventListener('click', () => action('MARK_CURRENCY_TRANSACTION_APPLIED', { transactionId: button.dataset.markStationReward }))); document.querySelectorAll('[data-mark-player-station-rewards]').forEach(button => button.addEventListener('click', () => action('MARK_PLAYER_STATION_REWARDS_APPLIED', { participantId: button.dataset.markPlayerStationRewards }))); document.querySelector('#preview')?.addEventListener('change', event => { previewParticipantId = event.target.value || null; render(); }); document.querySelector('#previewClose')?.addEventListener('click', () => { previewParticipantId = null; render(); }); document.querySelectorAll('[data-test-pack]').forEach(select => select.addEventListener('change', () => select.value && action('TEST_SELECT_PACK', { participantId: select.dataset.testPack, packId: select.value }))); document.querySelectorAll('[data-mark-purchase]').forEach(button => button.addEventListener('click', () => action('MARK_PURCHASE_APPLIED', { transactionId: button.dataset.markPurchase }))); document.querySelectorAll('[data-approve-transfer]').forEach(button => button.addEventListener('click', () => action('APPROVE_TRANSFER', { transferId: button.dataset.approveTransfer }))); document.querySelectorAll('[data-reject-transfer]').forEach(button => button.addEventListener('click', () => action('REJECT_TRANSFER', { transferId: button.dataset.rejectTransfer }))); document.querySelectorAll('[data-mark-transfer]').forEach(button => button.addEventListener('click', () => action('MARK_TRANSFER_APPLIED', { transferId: button.dataset.markTransfer }))); document.querySelectorAll('[data-unlock]').forEach(button => button.addEventListener('click', () => action('UNLOCK_PLAYER', { participantId: button.dataset.unlock }))); document.querySelectorAll('[data-hp]').forEach(button => button.addEventListener('click', () => { const hp = prompt('補正後HP（0～15）', button.dataset.current); if (hp !== null) action('ADJUST_HP', { participantId: button.dataset.hp, hp: Number(hp), reason: 'GMテスト用補正' }); })); document.querySelector('#markPlaytestInterrupted')?.addEventListener('click', () => action('MARK_PLAYTEST_INTERRUPTED')); document.querySelectorAll('[data-playtest-observation-status]').forEach(button => button.addEventListener('click', () => action('SET_PLAYTEST_OBSERVATION', { observationId: button.dataset.playtestObservationStatus, status: button.dataset.status }))); document.querySelectorAll('[data-save-playtest-note]').forEach(button => button.addEventListener('click', () => { const id = button.dataset.savePlaytestNote; const note = document.querySelector(`[data-playtest-observation-note="${id}"]`)?.value || ''; action('SET_PLAYTEST_OBSERVATION', { observationId: id, status: 'NOTE', note }); })); document.querySelectorAll('[data-export-playtest]').forEach(button => button.addEventListener('click', () => exportPlaytest(button.dataset.exportPlaytest))); const previewMe = state.testPlayers?.find(player => player.participantId === previewParticipantId); if (previewMe && state.testMode) { if (state.phase === 'PACK_SELECTION') bindPack(previewMe, true); else if (['TURN_SELECTION', 'TURN_RESULT'].includes(state.phase)) bindTurn(previewMe, true); else if (state.phase === 'ENDING') bindPlaytestSurvey(previewMe, true); bindPreview(previewMe); } }

function bindGameGuide() { document.querySelector('#openGameGuide')?.addEventListener('click', () => action('OPEN_GAME_GUIDE')); document.querySelector('#advanceGameGuide')?.addEventListener('click', () => action('ADVANCE_GAME_GUIDE')); }
function bindPrimaryNarrativeControls() { const control = document.querySelector('.gm-action .primary-control'); if (!control) return; const configuration = state.phase === 'INTRODUCTION' ? { type: 'ADVANCE_INTRODUCTION', label: state.introductionStep >= INTRODUCTION_LINES.length ? '自己紹介8分へ' : '次へ' } : state.phase === 'GAME_GUIDE' ? { type: 'ADVANCE_GAME_GUIDE', label: state.gameGuide?.step >= state.gameGuide?.lines.length ? 'パック選択へ' : '次へ' } : state.phase === 'STATION_INTRODUCTION' ? { type: 'ADVANCE_STATION_INTRODUCTION', label: state.stationIntroduction?.step >= state.stationIntroduction?.lines.length ? `${state.station?.name || '次の地獄'}を開始` : '次へ' } : state.phase === 'REWARD_NARRATION' ? { type: 'ADVANCE_REWARD_NARRATION', label: state.rewardNarration?.step >= state.rewardNarration?.lines.length ? state.stationResult?.noCurrencyRewards ? '最終順位へ' : '冥貨反映待機へ' : '次へ' } : state.phase === 'FREE_TIME_INTRO' ? { type: 'ADVANCE_FREE_TIME_INTRODUCTION', label: state.freeTimeIntroduction?.step >= state.freeTimeIntroduction?.lines.length ? '自由時間を開始' : '次へ' } : null; if (!configuration) return; control.innerHTML = `<button type="button" id="primaryNarrativeAdvance" class="primary-action">${esc(configuration.label)}</button>`; control.querySelector('#primaryNarrativeAdvance')?.addEventListener('click', () => action(configuration.type)); }
function addGameGuideTestOption() { const selector = document.querySelector('#testPhase'); if (!selector || selector.querySelector('[value="GAME_GUIDE"]')) return; const option = new Option('ゲーム説明', 'GAME_GUIDE', false, state.phase === 'GAME_GUIDE'); selector.add(option, 2); }
